class Solution {
public:
    int countSuffix(vector<int>& nums, vector<int>& target) {
        int n = nums.size();

        // Check frequency equality using a fixed-size array
        int freq[100001] = {0};
        for (int i = 0; i < n; i++) {
            freq[nums[i]]++;
            freq[target[i]]--;
        }
        for (int i = 0; i <= 100000; i++) {
            if (freq[i] != 0) return 0;
        }

        // Longest matching prefix length
        int p = 0;
        while (p < n && nums[p] == target[p]) p++;

        // Start of longest non-increasing suffix of target
        int q = n - 1;
        while (q > 0 && target[q - 1] >= target[q]) q--;

        // Count valid indices: q <= i <= min(p, n-1)
        int upper = min(p, n - 1);
        return max(0, upper - q + 1);
    }
};
